// entity 5
// "portal" is an explicit BSP38Loader override (see #parseExplicitPortalKeys):
// this brush sits entirely on the west side, nowhere near the doorway, so the
// geometric heuristic in #computeModelPortalMap would never assign it a
// portal on its own — proves the explicit-key escape hatch actually takes
// effect rather than just agreeing with what auto-derivation would find.
{
"classname" "trigger_multiple"
"wait" "-1"
"portal" "1"
// brush 0
{
( -96 -32 48 ) ( -32 32 48 ) ( -32 -32 48 ) e1u1/box1_5 0 0 0 1 1
( -96 32 16 ) ( -32 -32 16 ) ( -32 32 16 ) e1u1/box1_5 0 0 0 1 1
( -96 -32 16 ) ( -96 32 16 ) ( -96 -32 48 ) e1u1/box1_5 0 0 0 1 1
( -32 -32 16 ) ( -32 -32 48 ) ( -32 32 16 ) e1u1/box1_5 0 0 0 1 1
( -96 -32 16 ) ( -96 -32 48 ) ( -32 -32 16 ) e1u1/box1_5 0 0 0 1 1
( -96 32 16 ) ( -32 32 16 ) ( -96 32 48 ) e1u1/box1_5 0 0 0 1 1
}
}
// entity 6
// func_door filling the same doorway gap as the func_areaportal brush above
// (entity 4), same footprint by design: real Q2 mapping convention pairs a
// visible/solid door brush with a separate CONTENTS_AREAPORTAL brush in the
// same physical location. Exercises BSP38Loader#computeModelPortalMap, which
// derives modelPortalMap['*N'] from this brush's own compiled bounds without
// needing any target/targetname link to entity 4.
{
"classname" "func_door"
"angle" "90"
"speed" "100"
"wait" "2"
"lip" "8"
// brush 0
{
( -8 -16 96 ) ( 8 16 96 ) ( 8 -16 96 ) e1u1/box1_5 0 0 0 1 1
( -8 16 0 ) ( 8 -16 0 ) ( 8 16 0 ) e1u1/box1_5 0 0 0 1 1
( -8 -16 0 ) ( -8 16 0 ) ( -8 -16 96 ) e1u1/box1_5 0 0 0 1 1
( 8 -16 0 ) ( 8 -16 96 ) ( 8 16 0 ) e1u1/box1_5 0 0 0 1 1
( -8 -16 0 ) ( -8 -16 96 ) ( 8 -16 0 ) e1u1/box1_5 0 0 0 1 1
( -8 16 0 ) ( 8 16 0 ) ( -8 16 96 ) e1u1/box1_5 0 0 0 1 1
}
}
